    internal static bool IsPunctuation(Rune rune)
    {
        var value = rune.Value;
        var left = 0;
        var right = Ranges.Length / 2 - 1;
        while (left <= right)
        {
            var middle = left + (right - left) / 2;
            if (value < Ranges[middle * 2]) right = middle - 1;
            else if (value > Ranges[middle * 2 + 1]) left = middle + 1;
            else return true;
        }
        return false;
    }
